// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(address(0), address(0), 1e18, 1e18, 0, 5000, bytes32(0), false, false);

        vm.prank(address(1));
        bool setSucceeded;
        try c.setFeeRate(1000) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        uint256 feeRateAfter = c.feeRate();

        assertTrue(feeRateAfter == 5000);
    }
}
